FROM public.books b JOIN public.chapters c ON c.book_id=b.id AND c.slug='europe' JOIN public.topics t ON t.chapter_id=c.id AND t.slug='ancient-history-mcq-review-674'
WHERE b.title='Jubayer''s GK' ON CONFLICT (canonical_hash) DO UPDATE SET content=EXCLUDED.content,confidence=EXCLUDED.confidence;
INSERT INTO public.gk_notes (book_id,chapter_id,topic_id,title,content,source_page,source_section,display_order,confidence,canonical_hash)
SELECT b.id,c.id,t.id,'Renaissance scope boundary','The scan’s single-origin, “father/forerunner,” and invention claims are not imported as unqualified facts. The approved record preserves a broader, source-supported Italian and Florentine cultural-history scope.',675,'Renaissance scope boundary',675,'high'::confidence_level,'1d766f36ca14bd3bf5db49170a1ac14417c4bc66ce9606b7b3c2ee62a2750514'
FROM public.books b JOIN public.chapters c ON c.book_id=b.id AND c.slug='europe' JOIN public.topics t ON t.chapter_id=c.id AND t.slug='renaissance-675'
WHERE b.title='Jubayer''s GK' ON CONFLICT (canonical_hash) DO UPDATE SET content=EXCLUDED.content,confidence=EXCLUDED.confidence;
