SELECT b.id,c.id,t.id,'Reformation and labor-history boundary','The source’s theological characterizations, compressed legal effects, and “revolution” labels are withheld. Approved records preserve only narrowly sourced historical context.',676,'Reformation and labor-history boundary',676,'high'::confidence_level,'015f7f027234a716716fbaba147b5f1bf3b0a2485ad9f28285370a9868cbeff6'
FROM public.books b JOIN public.chapters c ON c.book_id=b.id AND c.slug='europe' JOIN public.topics t ON t.chapter_id=c.id AND t.slug='reform-labor-agriculture-676'
WHERE b.title='Jubayer''s GK' ON CONFLICT (canonical_hash) DO UPDATE SET content=EXCLUDED.content,confidence=EXCLUDED.confidence;
INSERT INTO public.gk_notes (book_id,chapter_id,topic_id,title,content,source_page,source_section,display_order,confidence,canonical_hash)
SELECT b.id,c.id,t.id,'Industrial-chronology boundary','The scan’s single start date, universal causal claims, and four-stage Industrial Revolution chronology are withheld pending primary or scholarly corroboration. Coal-and-steam factory context is retained with a precise institutional source.',677,'Industrial-chronology boundary',677,'high'::confidence_level,'d77efd0cba08e67575a63a908e9bb780aa2206d5203163d98b1711dc47f4844b'
FROM public.books b JOIN public.chapters c ON c.book_id=b.id AND c.slug='europe' JOIN public.topics t ON t.chapter_id=c.id AND t.slug='industrial-revolution-677'
WHERE b.title='Jubayer''s GK' ON CONFLICT (canonical_hash) DO UPDATE SET content=EXCLUDED.content,confidence=EXCLUDED.confidence;
INSERT INTO public.gk_notes (book_id,chapter_id,topic_id,title,content,source_page,source_section,display_order,confidence,canonical_hash)
SELECT b.id,c.id,t.id,'Political-history boundary','Ideological, ranking, current-status, diplomatic-causation, and simplified state-formation claims are withheld. Approved entries use neutral historic context tied to specific independent sources.',678,'Political-history boundary',678,'high'::confidence_level,'f060f286de8e65095233f99542eb63cc28ef9571708230ab726367e7e2032279'
FROM public.books b JOIN public.chapters c ON c.book_id=b.id AND c.slug='europe' JOIN public.topics t ON t.chapter_id=c.id AND t.slug='twentieth-century-revolutions-678'
WHERE b.title='Jubayer''s GK' ON CONFLICT (canonical_hash) DO UPDATE SET content=EXCLUDED.content,confidence=EXCLUDED.confidence;

